-(void)scanToc:(MKNode *)node withRange:(NSRange) range {

    NSArray<NSValue *> *values = [self.content findAllRanges:@"[toc]" withCompareOption: NSCaseInsensitiveSearch range:range];
    for (NSValue *value in values) {
        NSRange range = value.rangeValue;
        ToCNode *toc = [[ToCNode alloc] initWithOffset: range.location length:5];
        [node addChild:toc];
    }
}


- (void)tokenize:(MKNode * _Nonnull)node nodeRange:(NSRange)nodeRange {
    parentNode = node;
    range = nodeRange;
    tokens = [NSMutableArray arrayWithCapacity: (range.length / 2)];
    NSCharacterSet *actionCharset = [LineParser buildTokens];
    for (NSUInteger i = range.location; i <= range.location + range.length - 1; i++) {
        unichar current = [self.content characterAtIndex:i];
        if ([actionCharset characterIsMember:current]) {
            TokenLocation *found = [[TokenLocation alloc] initWithToken:current location:i];
            [tokens addObject:found];
        }
    }
}
- (void)scanBlocks:(MKNode *)line withRange:(NSRange)range {

    [self scanBeginTag:"==" endTag:"==" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"mark" start:start end:end tagBeginLength:2 tagEndLength:2];
    }];
    [self scanBeginTag:"$" endTag:"$" canEndWithNewLine:NO exclusive:YES withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"math_inline" start:start end:end tagBeginLength:1 tagEndLength:1];
    }];
    [self scanBeginTag:"***" endTag:"***" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"em_strong_emphasis" start:start end:end tagBeginLength:3 tagEndLength:3];
    }];
    [self scanBeginTag:"**" endTag:"**" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"strong_emphasis" start:start end:end tagBeginLength:2 tagEndLength:2];
    }];
    [self scanBeginTag:"__" endTag:"__" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"strong_emphasis" start:start end:end tagBeginLength:2 tagEndLength:2];
    }];
    [self scanBeginTag:"~~" endTag:"~~" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"del" start:start end:end tagBeginLength:2 tagEndLength:2];
    }];
    [self scanBeginTag:"*" endTag:"*" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"emphasis" start:start end:end tagBeginLength:1 tagEndLength:1];
    }];
    [self scanBeginTag:"_" endTag:"_" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"emphasis" start:start end:end tagBeginLength:1 tagEndLength:1];
    }];
    [self scanBeginTag:"~" endTag:"~" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"emphasis" start:start end:end tagBeginLength:1 tagEndLength:1];
    }];
    [self scanBeginTag:"::" endTag:"::" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        unichar signal = [self.content characterAtIndex:start + 2];
        NSString *nodeType = @"mark_pen_red";
        if (signal == 'y' || signal == 'Y') {
            nodeType = @"mark_pen_yellow";
        } else if (signal == 'g' || signal == 'G') {
            nodeType = @"mark_pen_green";
        }

        [self handlBlock:nodeType start:start end:end tagBeginLength:3 tagEndLength:2];
    }];
}

-(void)parse: (MKNode *) line withRange:(NSRange)range {
    [self tokenize:line nodeRange:range];
    [self scanBlocks:line withRange:range];
    [self scanToc:line withRange: range];
    int proceeded = -1;
    for (TokenLocation *tokenLocation in tokens) {

        int i = tokenLocation.location;
        if (proceeded >= i) {
            continue;
        }
        proceeded = i;
        unichar ch = tokenLocation.token;
        switch (ch) {
            case '!':
            {
                if (i >= range.length - 1 
                    || [self.content characterAtIndex: i + 1] != '[') {
                    continue;
                }
                i++;

                NSRange remainingRange = NSMakeRange( i + 1, range.length - (i + 1 - range.location));
                NSArray<NSNumber*>* posArray = [self detectPositions:@"]()" inRange:remainingRange];
                if (posArray.count == 3 && posArray[0].intValue + 1 == posArray[1].intValue) {
                    // ![]()
                    [self onImage:i line:line  posArray:posArray withRange:range];
                    i +=  posArray[2].intValue + 1;
                } else {
                    // check image reference defintion
                    NSArray<NSNumber*>* posArray2 = [self detectPositions:@"][]"  inRange:remainingRange];
                    if (posArray2.count == 3 && posArray2[0].intValue + 1 == posArray2[1].intValue) {
                        //![][] is reference usage
                        NSString* title = [self.content ranged:NSMakeRange(i + 1, posArray2[0].intValue - i + 1 )];

                        NSString* url = [self.content ranged:NSMakeRange(i  + posArray2[0].intValue + 3, posArray2[2].intValue - posArray2[1].intValue - 1)];
                        ReferenceUsage* refer = [[ReferenceUsage alloc] initWithOffset:   i - 1 length:posArray2[2].integerValue - i + 4];
                        refer.type = ImageRefernece;
                        refer.key = url.lowercaseString;
                        refer.title = title;
                        [line addChild:refer];
                        i += posArray2[2].intValue + 1 + 1;
                    }
                }
            }
                break;
            case '^':
                if (i + 3 >= range.length + range.location - 1) continue;
                if ([self.content characterAtIndex:i+1] == '[') {
                    NSRange remainingRange = NSMakeRange(i + 2 , range.length - (i  - range.location) - 2 );

                    NSArray<NSNumber *> *posArray = [self detectPositions:@"]" inRange:remainingRange];
                    if (posArray.count == 1) {
                        // ^[]
                        NSRange subRange = NSMakeRange(i + 2,posArray[0].intValue);
                        NSString *content = [NSString stringWithFormat:@"^[%@]", [self.content ranged:subRange]];
                        Footnote *note = [[Footnote alloc] initWithOffset:  i content:content];

                        FootnoteUsage *usage = [[FootnoteUsage alloc] initWithOffset: i content:content];
                        usage.note = note;
                        [usage.children addObject:note];
                        [line addChild:usage];
                        i += posArray[0].intValue + 2;
                    }
                }
                break;
            case '[':
            {
                if (i+1 >= range.length + range.location - 1) continue;
                NSRange remainingRange = NSMakeRange(i + 1, range.length - (i + 1 - range.location));

                NSArray<NSNumber*>* posArrayFootnote = [self detectPositions:@"^]:" inRange: remainingRange];
                if(posArrayFootnote.count >= 2  && posArrayFootnote[0].intValue == 0){
                    NSString *remaining = [self.content ranged:remainingRange];
                    //[^]: or [^]
                    if (posArrayFootnote.count == 3
                        && posArrayFootnote[1].intValue + 1 == posArrayFootnote[2].intValue) {
                        // [^]:
                        NSString *content = [NSString stringWithFormat:@"[%@", remaining ];
                        Footnote *footnote = [[Footnote alloc] initWithOffset: i content:content];
                        [line addChild:footnote];
